	local lp = self.Services.Players.LocalPlayer;
	local role = self:GetPlayerRole(lp);
	local color = self:GetRoleColor(role);
	local selBox = self.Preview.Model:FindFirstChild("PreviewESP_Box");
	if self.Config.Toggles.LocalESP then
		if not selBox then
			selBox = Instance.new("SelectionBox");
			selBox.Name = "PreviewESP_Box";
			selBox.LineThickness = 0.05;
			selBox.SurfaceTransparency = 0.55;
			selBox.Adornee = self.Preview.Model;
			selBox.Parent = self.Preview.Model;
		end
		selBox.Color3 = color;
		selBox.SurfaceColor3 = color;
		selBox.Visible = true;
		for _, p in ipairs(self.Preview.Model:GetDescendants()) do
			if (p:IsA("BasePart") and not p:GetAttribute("OrigMaterial")) then
				p:SetAttribute("OrigMaterial", p.Material.Name);
				p:SetAttribute("OrigColor", p.Color);
				p.Material = Enum.Material.Neon;
				p.Color = color;
			elseif p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\224\141\227\225\185\195\158\228", "\233\162\236\144\132")) then
				p.Material = Enum.Material.Neon;
				p.Color = color;
			end
		end
		if self.Preview.AuraEmitter then
			self.Preview.AuraEmitter.Color = ColorSequence.new(color);
		end
	else
		if selBox then
			selBox.Visible = false;
		end
		for _, p in ipairs(self.Preview.Model:GetDescendants()) do
			if (p:IsA("BasePart") and p:GetAttribute("OrigMaterial")) then
				local origMat = p:GetAttribute("OrigMaterial");
				local origCol = p:GetAttribute(LUAOBFUSACTOR_DECRYPT_STR_0("\157\214\247\29\154\249\83\189\214", "\63\210\164\158\122\217\150"));
				pcall(function()
					p.Material = Enum.Material[origMat] or Enum.Material.SmoothPlastic;
					if origCol then
						p.Color = origCol;
					end
				end);
			end
		end
		if self.Preview.AuraEmitter then
			self.Preview.AuraEmitter.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255));
		end
	end
end;
