Hub.IsCharacterOrGunPart = function(self, part)
	if not part then
		return false;
	end
	for _, p in ipairs(self.Services.Players:GetPlayers()) do
		if (p.Character and part:IsDescendantOf(p.Character)) then
			return true;
		end
	end
	local gun = self.Services.Workspace:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\2\161\238\117\55\187\240", "\49\69\212\128"));
	if (gun and part:IsDescendantOf(gun)) then
		return true;
	end
	return false;
