	end
	local targetTrans = math.clamp(self.Config.Values.XRayTransparency / 100, 0, 1);
	for part, _ in pairs(self.World.OriginalTransparency) do
		if (part and part.Parent and (typeof(part) == LUAOBFUSACTOR_DECRYPT_STR_0("\21\193\20\217\36\0\31\57", "\124\92\175\103\173\69\110")) and part:IsA("BasePart")) then
