Hub.IsCoinBagFull = function(self)
	local isFull = false;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild("PlayerGui");
		local mg = pgui and pgui:FindFirstChild("MainGUI");
