		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\55\150\10\167\160", "\41\113\228\107\202\197\54\184")) and bagFrame.Visible) then
					local icon = bagFrame:FindFirstChild("CurrencyFrame") and bagFrame.CurrencyFrame:FindFirstChild("Icon");
					local coinsLabel = icon and icon:FindFirstChild("Coins");
					local count = tonumber((coinsLabel and coinsLabel.Text) or "0") or 0;
					if (count >= (self.Config.Values.AutoFarmBagLimit or 40)) then
						isFull = true;
