	local pg = lp and lp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\180\206\4\233\223\107\163\215\12", "\25\228\162\101\144\186"));
	if not pg then
		return;
	end
	for _, desc in ipairs(pg:GetDescendants()) do
		if ((desc.Name == "ValueBadge") or (desc.Name == "MM2TotalValueHeader") or (desc.Name == "TotalValHeader")) then
			pcall(function()
				desc:Destroy();
			end);
		end
	end
end;
Hub.CleanTradePanel = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local pg = lp and lp:FindFirstChild("PlayerGui");
	if pg then
		for _, desc in ipairs(pg:GetDescendants()) do
			if ((desc.Name == "TradeStatusPanel") or (desc.Name == "SV_Total")) then
				pcall(function()
					desc:Destroy();
				end);
			end
		end
	end
	if self.State.Gui then
		local pnl = self.State.Gui:FindFirstChild("TradeStatusPanel");
		if pnl then
			pcall(function()
				pnl:Destroy();
			end);
		end
	end
end;
Hub.CleanValuesBadges = function(self)
	self:CleanInventoryBadges();
	self:CleanTradePanel();
end;
Hub.ProcessInventoryWindow = function(self, inv)
	if (not inv or not inv:IsA("GuiObject") or not inv.Visible) then
		local old = inv and inv:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\101\27\235\58\253\240\73\58\143\15\254\241\77\30\188\15\246\225\90", "\132\40\86\217\110\146"), true);
		if old then
			old.Visible = false;
		end
		return;
	end
	local mainFrame = inv:FindFirstChild("Main");
	local weapons = mainFrame and mainFrame:FindFirstChild("Weapons");
	if ((inv.Name == "ViewProfile") and (not weapons or not weapons.Visible)) then
		local profileTab = mainFrame and mainFrame:FindFirstChild("Profile");
		if (profileTab and profileTab.Visible) then
			local showcase = profileTab:FindFirstChild("ItemShowcase", true);
			local cont = showcase and showcase:FindFirstChild("Container");
			if cont then
				for _, desc in ipairs(cont:GetDescendants()) do
					if (desc.Name == "NewItem") then
						local details = self:GetSlotItemDetails(desc);
						local itemName = (details and details.itemName) or self:GetItemNameFromSlot(desc);
						if (itemName and (itemName ~= "") and (itemName ~= "Loading...")) then
							local val = self:GetSkinValue(itemName, details);
							self:AttachItemValueBadge(desc, val);
						end
					end
				end
			end
		end
		local old = inv:FindFirstChild("MM2TotalValueHeader", true);
		if old then
			old.Visible = false;
		end
		return;
	end
	if (not weapons or not weapons.Visible) then
		local old = inv:FindFirstChild("MM2TotalValueHeader", true);
		if old then
			old.Visible = false;
		end
		return;
	end
	local itemsFrame = weapons:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\87\223\34\177\180", "\62\30\171\71\220\199\19\156"));
	if not itemsFrame then
		return;
	end
	local seenSlots = {};
	local totalVal = 0;
	local totalItems = 0;
	for _, desc in ipairs(itemsFrame:GetDescendants()) do
		if ((desc.Name == LUAOBFUSACTOR_DECRYPT_STR_0("\110\64\187\31\73\204\34", "\45\32\37\204\86\61\169\79")) and not seenSlots[desc]) then
			seenSlots[desc] = true;
			local details = self:GetSlotItemDetails(desc);
			local itemName = (details and details.itemName) or self:GetItemNameFromSlot(desc);
			if (itemName and (itemName ~= "") and (itemName ~= "Loading...")) then
				local amountLbl = desc:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\118\90\11\168\180\117\91\80\23", "\28\53\53\101\220\213")) and desc.Container:FindFirstChild("Amount");
				local amtText = (amountLbl and amountLbl.Text) or "";
				local qty = tonumber(amtText:match(LUAOBFUSACTOR_DECRYPT_STR_0("\69\25\12\10\19", "\191\109\60\104\33\58\193\48"))) or 1;
				local val = self:GetSkinValue(itemName, details);
				self:AttachItemValueBadge(desc, val);
				local numVal = ((type(val) == "number") and val) or tonumber(val);
				if (numVal and (numVal > 0)) then
					totalVal = totalVal + (numVal * qty);
					totalItems = totalItems + qty;
				end
			end
		end
	end
	local header = weapons:FindFirstChild("MM2TotalValueHeader");
	if not header then
		local inTabs = weapons:FindFirstChild("MM2TotalValueHeader", true);
		if (inTabs and (inTabs.Parent ~= weapons)) then
			inTabs:Destroy();
		end
		header = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\161\197\25\234\130", "\135\231\183\120"));
		header.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\203\39\30\208\58\14\168\234\60\77\232\32\31\129\227\11\72\225\39", "\201\134\106\44\132\85\122");
		header.Size = UDim2.new(0, 115, 0, 24);
		header.Position = UDim2.new(1, -125, 0, 8);
		header.BackgroundColor3 = Color3.fromRGB(16, 18, 26);
		header.BackgroundTransparency = 0.15;
		header.ZIndex = 9999;
		header.Parent = weapons;
		self:Corner(header, 5);
		self:Stroke(header, Color3.fromRGB(55, 65, 90), 1);
		local txt = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\2\9\111\43\45\13\202\38\58", "\67\86\108\23\95\97\108\168"));
		txt.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\144\55\88\11\168\16\208\72\176", "\48\196\88\44\106\196\68\181");
		txt.Size = UDim2.new(1, 0, 1, 0);
		txt.BackgroundTransparency = 1;
		txt.Font = Enum.Font.GothamBold;
		txt.TextColor3 = Color3.fromRGB(255, 215, 80);
		txt.TextSize = 11;
		txt.ZIndex = 10000;
		txt.Parent = header;
	end
	header.Visible = true;
	local txt = header:FindFirstChild("TotalText");
	if txt then
		txt.Text = "Total: " .. self:FormatNumber(totalVal);
	end
end;
