Hub.DecodeSkinEnum = function(self, raw)
	local group, item = string.match(raw, LUAOBFUSACTOR_DECRYPT_STR_0("\133\108\172\58\75\99\228\182\128\12\181\16\123\109\227\187\245\1\153\106\81\25\151\181\242\13", "\158\219\41\194\79\38\70\202"));
	if not group then
		return nil;
	end
	local ok, val = pcall(function()
		return Enum[group][item];
	end);
	return (ok and val) or nil;
end;
Hub.DecodeSkinProperty = function(self, current, raw)
	local k = type(raw);
	if ((k == LUAOBFUSACTOR_DECRYPT_STR_0("\77\48\34\0\235\196", "\232\35\69\79\98\142\182")) or (k == "boolean")) then
		return raw;
