	self:BackupSkinProp(display, {[LUAOBFUSACTOR_DECRYPT_STR_0("\173\6\115\69\111", "\28\217\116\18\43")]=display.Transparency,[LUAOBFUSACTOR_DECRYPT_STR_0("\223\88\210", "\92\178\55\182\52\176\206")]=display.LocalTransparencyModifier});
	self:ClearSkinGarbage(display);
	display.LocalTransparencyModifier = 1;
	pcall(function()
		display.Transparency = 1;
	end);
	local body = self:CreateSkinPart(rec);
	if not body then
		return false;
